using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 void ComicCrafting(){var b=Panel("WORKSHOP  /  TIER "+game.Craft.BenchTier);coopMenu="craft";Text(b,"DISCOVERED TIER "+game.Craft.UnlockedTier+"   /   CATALYSTS "+game.Life.NightEssence+"   /   BANDAGES "+game.Life.Bandages+"   /   BAG KITS "+game.Life.Bags);var row=new HBoxContainer{CustomMinimumSize=new Vector2(880,400)};row.AddThemeConstantOverride("separation",22);b.AddChild(row);var list=new ItemList{CustomMinimumSize=new Vector2(370,400),SizeFlagsVertical=Control.SizeFlags.ExpandFill};list.AddThemeStyleboxOverride("panel",Style(new Color(.08f,.11f,.11f),new Color(.26f,.31f,.27f),1,8));list.AddThemeColorOverride("font_color",new Color(.81f,.82f,.71f));list.AddThemeColorOverride("font_selected_color",new Color(.98f,.88f,.59f));list.AddThemeStyleboxOverride("selected",Style(new Color(.24f,.28f,.23f),new Color(.61f,.52f,.32f),1,8));row.AddChild(list);var details=new VBoxContainer{CustomMinimumSize=new Vector2(460,0),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(details);foreach(var r in ExpeditionRecipe.All)list.AddItem("T"+r.Tier+"  /  "+r.Name);void Select(int index){coopRecipeChoice=index;ClearChildren(details);var r=ExpeditionRecipe.All[index];var title=new Label{Text=r.Name.ToUpper(),AutowrapMode=TextServer.AutowrapMode.WordSmart};title.AddThemeFontSizeOverride("font_size",21);details.AddChild(title);details.AddChild(new HSeparator());details.AddChild(new Label{Text="REQUIRES  WORKSHOP "+r.Station+" / TIER "+r.Tier});for(int i=0;i<7;i++)if(r.Cost[i]>0){var l=new Label{Text=ExpeditionGame.ResourceNames[i].ToUpper()+"     "+game.Craft.Materials[i]+" / "+r.Cost[i]};l.AddThemeColorOverride("font_color",game.Craft.Materials[i]>=r.Cost[i]?new Color(.65f,.76f,.49f):new Color(.91f,.49f,.32f));details.AddChild(l);}details.AddChild(new Control{SizeFlagsVertical=Control.SizeFlags.ExpandFill});details.AddChild(new Label{Text=game.RecipeReason(r)});Button(details,"CRAFT "+r.Name.ToUpper(),()=>{if(!CoopRequest("craft",Array.IndexOf(ExpeditionRecipe.All,r).ToString()))game.CraftRecipe(r);ComicCrafting();});}list.ItemSelected+=index=>Select((int)index);list.Select(coopRecipeChoice);Select(coopRecipeChoice);Text(b,string.Join("   /   ",ExpeditionGame.ResourceNames.Select((n,i)=>n+" "+game.Craft.Materials[i])));Text(b,game.Notice);Button(b,"BACK TO WORLD",CloseMenu);}
 void Portrait(VBoxContainer parent){var holder=new SubViewportContainer{CustomMinimumSize=new Vector2(250,210),Stretch=true};parent.AddChild(holder);var viewport=new SubViewport{Size=new Vector2I(250,210),TransparentBg=true,OwnWorld3D=true,RenderTargetUpdateMode=SubViewport.UpdateMode.Always};holder.AddChild(viewport);var model=new Node3D{RotationDegrees=new Vector3(0,15,0)};viewport.AddChild(model);ArtCharacter(model,1,0,true);var key=new DirectionalLight3D{RotationDegrees=new Vector3(-35,-30,0),LightColor=new Color(1,.86f,.65f),LightEnergy=1.2f};viewport.AddChild(key);var fill=new DirectionalLight3D{RotationDegrees=new Vector3(20,160,0),LightColor=new Color(.53f,.67f,.74f),LightEnergy=.6f};viewport.AddChild(fill);var cam=new Camera3D{Position=new Vector3(0,1.1f,-2.3f),Current=true,Fov=50};viewport.AddChild(cam);cam.LookAt(new Vector3(0,.95f,0));}
 void ComicEquipment(){var b=Panel("LOADOUT / SURVIVOR");coopMenu="equipment";var row=new HBoxContainer{CustomMinimumSize=new Vector2(880,460)};row.AddThemeConstantOverride("separation",20);b.AddChild(row);var left=new VBoxContainer{CustomMinimumSize=new Vector2(360,0)};row.AddChild(left);Portrait(left);var scroll=new ScrollContainer{CustomMinimumSize=new Vector2(360,230)};left.AddChild(scroll);var guns=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(guns);foreach(int id in game.Craft.Weapons){int copy=id;Button(guns,(id==game.Craft.Weapon?"[EQUIPPED] ":"")+ExpeditionGame.GunNames[id]+" +"+game.Life.WeaponQuality[id]+"%",()=>{if(!CoopRequest("equip",copy.ToString()))game.Change(()=>game.Equip(copy));reloadClock=0;BuildGun();ComicEquipment();});}var right=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(right);right.AddChild(new Label{Text="CHEST ARMOR / RELICS"});right.AddChild(new HSeparator());var armorScroll=new ScrollContainer{CustomMinimumSize=new Vector2(475,390),SizeFlagsVertical=Control.SizeFlags.ExpandFill};right.AddChild(armorScroll);var armor=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};armorScroll.AddChild(armor);if(game.Profile.Items.Count==0)armor.AddChild(new Label{Text="NO ARMOR EQUIPPED\n\nRecover a relic from a dungeon\nor craft a chest plate at the workshop."});foreach(var item in game.Profile.Items){var copy=item;Button(armor,(game.Profile.Equipped==item.Id?"[EQUIPPED] ":"")+"T"+item.Level+" / "+item.Name+"\nARMOR "+item.Armor+"   VITALITY +"+item.Vitality,()=>{if(!CoopRequest("armor",copy.Id))game.Change(()=>game.Profile.Equipped=copy.Id);ComicEquipment();});}Text(b,"Armor reduces bite impact. Bandages stop bleeding; they do not restore health.");Button(b,"BACK TO WORLD",CloseMenu);}
}
